### Minimal Policy Example: Blocking `rm -rf`

```typescript
const restrictiveRm = defineCommand("rm-restricted", async (args, ctx) => {
  const cmdLine = ["rm", ...args].join(" ");

  // Approve only specific patterns
  const approved = /^rm\s+-f\s+\*\.log$/.test(cmdLine);

  if (!approved) {
    return { stdout: "", stderr: "rm -rf: not approved\n", exitCode: 1 };
  }

  // Approved commands can execute via ctx.exec()
  return ctx.exec("rm", args);
});

const bash = new Bash({ customCommands: [restrictiveRm] });
```

