export const load: PageServerLoad = async ({ params, cookies, locals }) => {
	return {
		post: {
			title: `Title for ${params.slug}`,
			content: `Content for ${params.slug}`
		},
		sessionId: cookies.get('sessionid') ?? null
	};
};
```

